import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Nav from './Nav'; // Import the Nav component
import AllOrders from './AllOrders'; // Import the AllOrders component
import AddOrder from './AddOrder';
import UpdateOrder from './UpdateOrder';

function App() {
  return (
    <Router>
      <div className="App">
        <Nav /> {/* Include the Nav component */}
        <Routes>
          <Route path="/" element={<Home />} /> {/* Define a Home component */}
          <Route path="/all-orders" element={<AllOrders />} />
          <Route path="/add-order" element={<AddOrder />} />
          <Route path="/update-order/:id" element={<UpdateOrder />} /> {/* Add this route */}
        </Routes>
      </div>
    </Router>
  );
}

//  Placeholder for the Home component
function Home() {
    return (
      <div>
        <h1>Home</h1>
        <p>Welcome to the Home page!</p>
      </div>
    );
  }

export default App;
